  float crack=bell(sin(a*11.0+sin(r*16.0)*.35),.055)*smoothstep(.10,.2,r)*(1.0-smoothstep(.3,.72,r));
  float crackGlow=crack*(1.0-smoothstep(.08,.65,age));
